/* Browsers expose voice names, not reliable gender/age metadata. Profiles are user assignments. */
const voiceProfiles={auto:'Automática',male:'Hombre',female:'Mujer',boy:'Niño',girl:'Niña'};
function cleanVoiceSettings(raw){raw=raw&&typeof raw==='object'?raw:{};const bindings={};for(const k of Object.keys(voiceProfiles))if(typeof raw.bindings?.[k]==='string')bindings[k]=raw.bindings[k].slice(0,500);return {profile:Object.hasOwn(voiceProfiles,raw.profile)?raw.profile:'auto',bindings,rate:Math.min(1.3,Math.max(.5,Number(raw.rate)||.85)),pitch:Math.min(1.5,Math.max(.5,Number(raw.pitch)||1))}}
state.voiceSettings=cleanVoiceSettings(state.voiceSettings);
function availableSpanishVoices(){return 'speechSynthesis'in window?window.speechSynthesis.getVoices().filter(v=>/^es(?:[-_]|$)/i.test(v.lang)):[]}
function voiceKey(v){return v.voiceURI||v.name+'|'+v.lang}
function chooseVoice(config,list){const key=config.bindings[config.profile];return list.find(v=>voiceKey(v)===key)||list.find(v=>v.default)||list[0]||null}
function voiceMessage(config,list){const key=config.bindings[config.profile];if(!list.length)return 'No hay voces en español disponibles todavía. Prueba Recargar voces o instala una voz española en los ajustes del dispositivo.';if(config.profile!=='auto'&&!key)return 'Este perfil aún no tiene una voz asignada. Escucha las voces disponibles y elige una. Por ahora se usará la voz española predeterminada.';if(key&&!list.some(v=>voiceKey(v)===key))return 'La voz guardada no está disponible en este dispositivo. Se usará otra voz española; puedes volver a elegir.';return 'Voz disponible. Algunas voces necesitan conexión; prueba el modo sin conexión en tu dispositivo.'}
function speakConfigured(text,config,force=false){if(!force&&!state.sound)return;if(!('speechSynthesis'in window)){alert('Este navegador no ofrece síntesis de voz.');return}const synth=window.speechSynthesis,list=availableSpanishVoices(),v=chooseVoice(config,list),u=new SpeechSynthesisUtterance(text);u.lang=v?.lang||'es-EC';u.rate=config.rate;u.pitch=config.pitch;if(v)u.voice=v;synth.cancel();synth.speak(u)}
say=function(t){speakConfigured(t,state.voiceSettings)};
const familyWithoutVoices=family;
family=function(){familyWithoutVoices();const panel=document.createElement('section');panel.className='panel';panel.innerHTML='<h2>Género y voz</h2><p>Elige un perfil y asígnale una voz del dispositivo. El navegador no identifica de forma fiable el género ni la edad: escucha la muestra para elegir.</p><label for="voiceProfile">Perfil de voz</label><select id="voiceProfile">'+Object.entries(voiceProfiles).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('')+'</select><label for="voiceChoice">Voz disponible en español</label><select id="voiceChoice"></select><p id="voiceStatus" class="hint" aria-live="polite"></p><label for="voiceRate">Velocidad</label><select id="voiceRate"><option value="0.65">Pausada</option><option value="0.85">Tranquila</option><option value="1">Normal</option><option value="1.15">Rápida</option></select><label for="voicePitch">Tono</label><select id="voicePitch"><option value="0.85">Un poco más grave</option><option value="1">Natural</option><option value="1.15">Un poco más agudo</option></select><p class="hint">Cambiar el tono no convierte una voz adulta en una voz infantil. Niño y Niña solo son perfiles; requieren asignar una voz infantil real si existe.</p><div class="bar"><button id="voicePreview">🔊 Escuchar muestra</button><button id="voiceSave">Guardar voz</button><button class="secondary" id="voiceRefresh">Recargar voces</button></div><p id="voiceSaved" aria-live="polite"></p>';app.prepend(panel);let draft=cleanVoiceSettings(state.voiceSettings);$('voiceProfile').value=draft.profile;$('voiceRate').value=String(draft.rate);if(!$('voiceRate').value)$('voiceRate').value='0.85';$('voicePitch').value=String(draft.pitch);if(!$('voicePitch').value)$('voicePitch').value='1';function refresh(){const list=availableSpanishVoices(),key=draft.bindings[draft.profile]||'';$('voiceChoice').innerHTML='<option value="">Predeterminada en español</option>'+list.map(v=>'<option value="'+escape(voiceKey(v))+'">'+escape(v.name+' · '+v.lang+(v.localService?' · del dispositivo':' · servicio de voz'))+'</option>').join('');$('voiceChoice').value=list.some(v=>voiceKey(v)===key)?key:'';$('voiceStatus').textContent=voiceMessage(draft,list)}function collect(){draft.rate=Number($('voiceRate').value);draft.pitch=Number($('voicePitch').value);return cleanVoiceSettings(draft)}$('voiceProfile').onchange=()=>{draft.profile=$('voiceProfile').value;refresh()};$('voiceChoice').onchange=()=>{draft.bindings[draft.profile]=$('voiceChoice').value;$('voiceStatus').textContent=voiceMessage(draft,availableSpanishVoices())};$('voiceRefresh').onclick=refresh;$('voicePreview').onclick=()=>speakConfigured('Hola, esta es mi voz en MeComunico. Quiero aprender y comunicarme.',collect(),true);$('voiceSave').onclick=()=>{state.voiceSettings=collect();save();$('voiceSaved').textContent='Preferencia de voz guardada.'};refresh();if('speechSynthesis'in window){const update=()=>{if(document.getElementById('voiceChoice')===panel.querySelector('#voiceChoice'))refresh();else window.speechSynthesis.removeEventListener('voiceschanged',update)};window.speechSynthesis.addEventListener('voiceschanged',update)}};
$('family').onclick=family;
